result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "tinyci/tinyci/spec.py", "content": """"Pipeline specification: parse and validate the YAML pipeline file."""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from typing import Any

import yaml


class SpecError(ValueError):
    """Raised when a pipeline spec is invalid."""


@dataclass
class Stage:
    name: str
    command: str
    env: dict[str, str] = field(default_factory=dict)
    inputs: list[str] = field(default_factory=list)
    artifacts: list[str] = field(default_factory=list)
    depends_on: list[str] = field(default_factory=list)


@dataclass
class Pipeline:
    name: str
    stages: dict[str, Stage]

    def topological_order(self) -> list[str]:
        """Return stage names in dependency order.

        Raises SpecError on unknown dependencies or dependency cycles.
        """
        order: list[str] = []
        state: dict[str, int] = {name: 0 for name in self.stages}  # 0=new 1=visiting 2=done

        def visit(name: str, stack: list[str]) -> None:
            if state[name] == 2:
                return
            if state[name] == 1:
                cycle = stack[stack.index(name):] + [name]
                raise SpecError(f"dependency cycle detected: {' -> '.join(cycle)}")
            state[name] = 1
            stack.append(name)
            for dep in self.stages[name].depends_on:
                visit(dep, stack)
            stack.pop()
            state[name] = 2
            order.append(name)

        for name in self.stages:
            visit(name, [])
        return order


def _expect_str_list(value: Any, what: str) -> list[str]:
    if value is None:
        return []
    if not isinstance(value, list) or not all(isinstance(v, str) for v in value):
        raise SpecError(f"{what} must be a list of strings")
    return value


def _expect_str_dict(value: Any, what: str) -> dict[str, str]:
    if value is None:
        return {}
    if not isinstance(value, dict):
        raise SpecError(f"{what} must be a mapping")
    out = {}
    for k, v in value.items():
        if not isinstance(k, str) or not isinstance(v, (str, int, float, bool)):
            raise SpecError(f"{what} must map string keys to scalar values")
        out[k] = str(v)
    return out


def load_pipeline(path: str | os.PathLike) -> Pipeline:
    """Load and validate a pipeline YAML file."""
    path = os.fspath(path)
    if not os.path.isfile(path):
        raise SpecError(f"pipeline file not found: {path}")
    with open(path, encoding="utf-8") as fh:
        raw = yaml.safe_load(fh)

    if not isinstance(raw, dict):
        raise SpecError("pipeline root must be a mapping")
    name = raw.get("name", os.path.splitext(os.path.basename(path))[0])
    stages_raw = raw.get("stages")
    if not isinstance(stages_raw, dict) or not stages_raw:
        raise SpecError("pipeline must define a non-empty 'stages' mapping")

    stages: dict[str, Stage] = {}
    for sname, body in stages_raw.items():
        if not isinstance(sname, str) or not sname:
            raise SpecError("stage names must be non-empty strings")
        if not isinstance(body, dict):
            raise SpecError(f"stage '{sname}' must be a mapping")
        command = body.get("command")
        if not isinstance(command, str) or not command.strip():
            raise SpecError(f"stage '{sname}' requires a 'command' string")
        stages[sname] = Stage(
            name=sname,
            command=command,
            env=_expect_str_dict(body.get("env"), f"stage '{sname}' env"),
            inputs=_expect_str_list(body.get("inputs"), f"stage '{sname}' inputs"),
            artifacts=_expect_str_list(body.get("artifacts"), f"stage '{sname}' artifacts"),
            depends_on=_expect_str_list(body.get("depends_on"), f"stage '{sname}' depends_on"),
        )

    # Validate dependencies reference known stages and no self-deps.
    for sname, st in stages.items():
        for dep in st.depends_on:
            if dep == sname:
                raise SpecError(f"stage '{sname}' cannot depend on itself")
            if dep not in stages:
                raise SpecError(f"stage '{sname}' depends on unknown stage '{dep}'")

    return Pipeline(name=str(name), stages=stages)
