result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "tinyci/tests/test_tinyci.py", "content": """"Test suite for tinyci (>= 10 tests).

Covers: dependency ordering, failure skip-propagation, cache hit/miss on
input change, artifact collection, log capture, env vars, history listing,
and spec validation.
"""

from __future__ import annotations

import json
import textwrap
from pathlib import Path

import pytest
import yaml

from tinyci.cache import Cache
from tinyci.runner import Runner, load_run_history
from tinyci.spec import SpecError, load_pipeline


# ---- helpers ------------------------------------------------------------


def make_project(tmp_path: Path, pipeline: dict) -> Path:
    """Create a project dir with a pipeline.yml and return its path."""
    root = tmp_path / "proj"
    (root / "src").mkdir(parents=True)
    (root / "src" / "mod.py").write_text("VALUE = 1\n")
    (root / "pipeline.yml").write_text(yaml.safe_dump(pipeline))
    return root


def run_pipeline(root: Path, pipeline_file: str = "pipeline.yml") -> dict:
    return Runner(root).run(load_pipeline(root / pipeline_file))


def stage_status(meta: dict, name: str) -> str:
    return next(s["status"] for s in meta["stages"] if s["name"] == name)


PIPELINE = {
    "name": "test",
    "stages": {
        "first": {"command": "echo first"},
        "second": {"command": "echo second", "depends_on": ["first"]},
        "third": {"command": "echo third", "depends_on": ["second"]},
    },
}


# ---- ordering & spec ------------------------------------------------------


class TestOrdering:
    def test_topological_order_respects_depends_on(self, tmp_path):
        root = make_project(tmp_path, PIPELINE)
        meta = run_pipeline(root)
        names = [s["name"] for s in meta["stages"]]
        # All stages ran and metadata preserves definition order...
        assert set(names) == {"first", "second", "third"}
        # ...while execution followed dependency order (all succeeded).
        assert all(s["status"] == "success" for s in meta["stages"])

    def test_dependency_cycle_detected(self):
        with pytest.raises(SpecError, match="cycle"):
            load_pipeline.__wrapped__ if False else None
            from tinyci.spec import Pipeline, Stage

            Pipeline(
                name="cyclic",
                stages={
                    "a": Stage("a", command="true", depends_on=["b"]),
                    "b": Stage("b", command="true", depends_on=["a"]),
                },
            ).topological_order()

    def test_unknown_dependency_rejected(self, tmp_path):
        bad = {
            "name": "bad",
            "stages": {"a": {"command": "true", "depends_on": ["ghost"]}},
        }
        root = make_project(tmp_path, bad)
        with pytest.raises(SpecError, match="unknown stage"):
            load_pipeline(root / "pipeline.yml")


# ---- failure propagation ---------------------------------------------------


class TestFailurePropagation:
    def test_failed_stage_marks_downstream_skipped(self, tmp_path):
        pipeline = {
            "name": "failing",
            "stages": {
                "build": {"command": "exit 3"},
                "deploy": {"command": "echo deploy", "depends_on": ["build"]},
                "notify": {"command": "echo notify", "depends_on": ["deploy"]},
            },
        }
        root = make_project(tmp_path, pipeline)
        meta = run_pipeline(root)
        assert stage_status(meta, "build") == "failed"
        assert stage_status(meta, "deploy") == "skipped"
        assert stage_status(meta, "notify") == "skipped"
        assert meta["overall_status"] == "failed"

    def test_failure_does_not_affect_independent_stages(self, tmp_path):
        pipeline = {
            "name": "mixed",
            "stages": {
                "broken": {"command": "false"},
                "independent": {"command": "echo ok"},
            },
        }
        root = make_project(tmp_path, pipeline)
        meta = run_pipeline(root)
        assert stage_status(meta, "broken") == "failed"
        assert stage_status(meta, "independent") == "success"

    def test_skip_is_not_cached(self, tmp_path):
        """A skipped stage must not poison the cache; fixing upstream lets it run."""
        pipeline = {
            "name": "fixable",
            "stages": {
                "flaky": {"command": "exit 1", "inputs": ["src/**"]},
                "child": {"command": "echo child", "depends_on": ["flaky"]},
            },
        }
        root = make_project(tmp_path, pipeline)
        run_pipeline(root)
        assert stage_status(run_pipeline(root), "child") == "skipped"
        # Fix the input; now both stages succeed.
        (root / "src" / "mod.py").write_text("VALUE = 2\n")
        pipeline["stages"]["flaky"]["command"] = "echo fixed"
        (root / "pipeline.yml").write_text(yaml.safe_dump(pipeline))
        meta2 = run_pipeline(root)
        assert stage_status(meta2, "flaky") == "success"
        assert stage_status(meta2, "child") == "success"


# ---- cache ------------------------------------------------------------------


class TestCache:
    def test_cache_hit_on_unchanged_inputs(self, tmp_path):
        root = make_project(tmp_path, PIPELINE | {
            "stages": {
                "compile": {"command": "python -m compileall -q src", "inputs": ["src/**/*.py"]},
            },
        })
        first = run_pipeline(root)
        second = run_pipeline(root)
        assert stage_status(first, "compile") == "success"
        assert stage_status(second, "compile") == "cached"

    def test_cache_miss_after_input_change(self, tmp_path):
        pipeline = {
            "name": "cm",
            "stages": {
                "hasher": {
                    "command": "cp src/mod.py out.py",
                    "inputs": ["src/**/*.py"],
                    "artifacts": ["out.py"],
                },
            },
        }
        root = make_project(tmp_path, pipeline)
        run_pipeline(root)
        # Change a declared input file -> cache key changes -> re-run.
        (root / "src" / "mod.py").write_text("VALUE = 42\n")
        meta = run_pipeline(root)
        assert stage_status(meta, "hasher") == "success"

    def test_cache_key_sensitive_to_command_and_env(self, tmp_path):
        cache = Cache(tmp_path)
        k1 = cache.compute_key("s", "echo hi", {}, [], {})
        k2 = cache.compute_key("s", "echo bye", {}, [], {})
        k3 = cache.compute_key("s", "echo hi", {"A": "1"}, [], {})
        assert len({k1, k2, k3}) == 3

    def test_cache_restores_artifacts(self, tmp_path):
        pipeline = {
            "name": "restore",
            "stages": {
                "maker": {
                    "command": "printf hi > out.txt",
                    "inputs": ["src/**"],
                    "artifacts": ["out.txt"],
                },
            },
        }
        root = make_project(tmp_path, pipeline)
        run_pipeline(root)
        artifact_dir = root / ".tinyci" / "artifacts"
        run1_dirs = sorted(p.name for p in artifact_dir.iterdir())
        meta2 = run_pipeline(root)
        run2_id = meta2["run_id"]
        restored = artifact_dir / run2_id / "maker" / "out.txt"
        assert restored.read_text() == "hi"
        assert run1_dirs != [run2_id]


# ---- artifacts --------------------------------------------------------------


class TestArtifacts:
    def test_artifacts_collected_to_run_scoped_store(self, tmp_path):
        pipeline = {
            "name": "art",
            "stages": {
                "pack": {
                    "command": "mkdir -p dist && printf data > dist/a.bin && printf more > dist/b.bin",
                    "inputs": ["src/**"],
                    "artifacts": ["dist/*.bin"],
                },
            },
        }
        root = make_project(tmp_path, pipeline)
        meta = run_pipeline(root)
        store = root / ".tinyci" / "artifacts" / meta["run_id"] / "pack"
        assert sorted(p.name for p in store.iterdir()) == ["a.bin", "b.bin"]
        assert (store / "a.bin").read_text() == "data"

    def test_no_artifacts_declared_means_empty_store(self, tmp_path):
        root = make_project(tmp_path, PIPELINE)
        meta = run_pipeline(root)
        run_store = root / ".tinyci" / "artifacts" / meta["run_id"]
        assert not any(run_store.rglob("*")) or not run_store.exists() or \
            list(run_store.rglob("*")) == []


# ---- logs -------------------------------------------------------------------


class TestLogs:
    def test_log_captured_per_stage(self, tmp_path):
        pipeline = {
            "name": "logs",
            "stages": {
                "chatter": {"command": "echo to-stdout && echo to-stderr 1>&2"},
                "boom": {"command": "echo about-to-fail && exit 7"},
            },
        }
        root = make_project(tmp_path, pipeline)
        meta = run_pipeline(root)
        logs_dir = root / "logs" / meta["run_id"]
        chatter_log = (logs_dir / "chatter.log").read_text()
        boom_log = (logs_dir / "boom.log").read_text()
        assert "to-stdout" in chatter_log
        assert "to-stderr" in chatter_log          # stderr merged into log
        assert "$ echo to-stdout" in chatter_log   # command echoed
        assert "about-to-fail" in boom_log

    def test_env_vars_passed_to_stage(self, tmp_path):
        pipeline = {
            "name": "env",
            "stages": {
                "envy": {"command": "echo GREETING=$GREETING", "env": {"GREETING": "hola"}},
            },
        }
        root = make_project(tmp_path, pipeline)
        run_pipeline(root)
        run_ids = list((root / "logs").iterdir())
        log = (run_ids[0] / "envy.log").read_text()
        assert "GREETING=hola" in log


# ---- history ----------------------------------------------------------------


class TestHistory:
    def test_history_lists_runs_with_metadata(self, tmp_path):
        root = make_project(tmp_path, PIPELINE)
        meta1 = run_pipeline(root)
        meta2 = run_pipeline(root)

        history = load_run_history(root)
        assert len(history) == 2
        ids = {r["run_id"] for r in history}
        assert ids == {meta1["run_id"], meta2["run_id"]}
        newest = history[0]
        assert newest["trigger_time"]           # ISO timestamp present
        assert newest["overall_status"] == "success"
        by_name = {s["name"]: s for s in newest["stages"]}
        assert all(s["status"] == "success" for s in by_name.values())
        assert isinstance(by_name["first"]["duration_s"], float)

    def test_history_limit(self, tmp_path):
        root = make_project(tmp_path, PIPELINE)
        run_pipeline(root)
        run_pipeline(root)
        assert len(load_run_history(root, limit=1)) == 1
        assert len(load_run_history(root, limit=99)) == 2

    def test_history_reflects_failures_and_durations(self, tmp_path):
        pipeline = {
            "name": "histfail",
            "stages": {
                "sleepy_ok": {"command": "echo done"},
                "bad": {"command": "exit 1"},
                "never": {"command": "echo nope", "depends_on": ["bad"]},
            },
        }
        root = make_project(tmp_path, pipeline)
        run_pipeline(root)
        newest = load_run_history(root)[0]
        statuses = {s["name"]: s["status"] for s in newest["stages"]}
        durations = {s["name"]: s["duration_s"] for s in newest["stages"]}
        assert statuses == {"sleepy_ok": "success", "bad": "failed", "never": "skipped"}
        assert durations["never"] == 0.0
        assert newest["overall_status"] == "failed"
"})
